*******************************************************************************
* v3tile.asm -- video3's tile mode on the host emulator.  GENERATED by
* bench/mkv3tile.py; edit the generator.
*
*   sh hardware/video3/bench/run-v3tile.sh
*
* plan 2.4 and 8.1.  A ONE-byte map on a FOUR-byte cell stride, 8bpp tiles with no per-cell colour limit,
* HSCROLL and VSCROLL one pixel at a time with their ring wraps, and a six-bit cell
* row.  The palette is loaded so that ANY sub-palette but 0 is bright green -
* so if the attribute path leaks into tile mode, the screen says so.
*
* Each scroll is set, allowed to settle, and only THEN marked at $C208/$C20A,
* so no frame is judged against a scroll the frame-start latch had not taken.
*******************************************************************************

VCTRL   EQU     $FF60
VSCROLL EQU     $FF61
VSCROLH EQU     $FF62
HSCROLL EQU     $FF63
HSCROLH EQU     $FF64
WPTR0   EQU     $FF68
WPTR1   EQU     $FF69
WPTR2   EQU     $FF6A
WADV    EQU     $FF6B
VDATA   EQU     $FF6C
VSTAT   EQU     $FF6D
PIDXL   EQU     $FF6E
PIDXH   EQU     $FF6F
PDATL   EQU     $FF70
PDATH   EQU     $FF71
TILEBAS EQU     $FF78
MAPBAS  EQU     $FF79
SIMPORT EQU     $FF2F

MKH     EQU     $C208
MKV     EQU     $C20A
tno     EQU     $C100
row     EQU     $C102

        ORG     $8000
        FCC     "6309"
        JMP     start

        SETDP   $FF
start   orcc    #$50
        lds     #$E000
        lda     #$FF
        tfr     a,dp
        clr     <VCTRL          display off, bitmap, WMODE 00
        clr     <WADV
        ldd     #$FFFF
        std     MKH
        std     MKV
        lda     #1
        sta     <TILEBAS
        lda     #2
        sta     <MAPBAS

* --- ⭐ EVERY sub-palette is the marker, then sub-palette 0 is the identity.
*     Tile mode drives ATTR to zero (plan 3), so nothing green may appear.
        clr     <PIDXL
        clr     <PIDXH
        ldx     #0
pm1     lda     #$E0
        sta     <PDATL
        lda     #$07
        sta     <PDATH
        leax    1,x
        cmpx    #0
        bne     pm1
        clr     <PIDXL
        clr     <PIDXH
        clrb
p01     stb     <PDATL
        stb     <PDATH
        incb
        bne     p01

* --- the bank: 256 tiles of 64 bytes, tile t pixel p = (t*7 + p*1) & $FF
        clr     tno
tl1     lda     tno
        clrb
        lsra
        rorb
        lsra
        rorb                    D = t * 64
        addd    #16384
        stb     <WPTR0
        sta     <WPTR1
        clr     <WPTR2
        lda     tno
        ldb     #7
        mul                     B = t * 7, low byte
        stb     row             the running pixel value
        ldb     #64
tl2     lda     row
        sta     <VDATA
        adda    #1
        sta     row
        decb
        bne     tl2
        inc     tno
        bne     tl1

* --- the map: one code byte a cell in lane 0 of a FOUR-byte cell (plan 2.4),
*     one VRAM row a cell row.  Lanes 1-3 are unused by the card, and get three
*     values that are never the cell's code, so a wrong stride or lane shows.
        ldx     #maptab
        clra
        ldb     #64
mr1     pshs    a,b
        lda     #2
        sta     <WPTR2
        lda     ,s
        lsla
        lsla
        sta     <WPTR1
        clr     <WPTR0
        ldy     #128
mr2     lda     ,x+
        sta     <VDATA          lane 0: the code
        eora    #$A5
        sta     <VDATA          lane 1: code xor $A5
        eora    #$99            lane 2: code xor $3C
        sta     <VDATA
        eora    #$C3            lane 3: code xor $FF
        sta     <VDATA
        leay    -1,y
        bne     mr2
        puls    a,b
        inca
        decb
        bne     mr1

